#include <iostream>
#include <vector>
using namespace std;

int main() {
    int n, bird;
    cin >> n >> bird;
    vector<int> forest(n);
    for (auto &x : forest) cin >> x;
    // Sticks on each side, ordered from nearest to farthest from the nest.
    vector<int> left, right;
    for (int i = bird - 1; i >= 0; i--)
        if (forest[i]) left.push_back(i);
    for (int i = bird + 1; i < n; i++)
        if (forest[i]) right.push_back(i);
    vector<int> answer;
    int total = 0;
    while (total < 100) {
        int k = answer.size();
        int index = (k % 2 == 0 ? right : left)[k / 2];
        answer.push_back(index);
        total += forest[index];
    }
    for (size_t i = 0; i < answer.size(); i++) cout << (i ? " " : "") << answer[i];
    cout << '\n';
}

import java.io.*;
import java.util.*;

public class Main {
    static final byte[] BUF = new byte[1 << 16];
    static int len, ptr;

    static int read() throws IOException {
        if (ptr == len) {
            len = System.in.read(BUF, 0, BUF.length);
            ptr = 0;
            if (len <= 0) {
                len = 0;
                return -1;
            }
        }
        return BUF[ptr++];
    }

    static long nextLong() throws IOException {
        int c = read();
        while (c != -1 && c <= ' ') c = read();
        boolean neg = c == '-';
        if (neg) c = read();
        long r = 0;
        while (c >= '0' && c <= '9') {
            r = r * 10 + (c - '0');
            c = read();
        }
        return neg ? -r : r;
    }

    public static void main(String[] args) throws IOException {
        int n = (int) nextLong(), bird = (int) nextLong();
        int[] forest = new int[n];
        for (int i = 0; i < n; i++) forest[i] = (int) nextLong();
        // Sticks on each side, ordered from nearest to farthest from the nest.
        List<Integer> left = new ArrayList<>(), right = new ArrayList<>();
        for (int i = bird - 1; i >= 0; i--)
            if (forest[i] != 0) left.add(i);
        for (int i = bird + 1; i < n; i++)
            if (forest[i] != 0) right.add(i);
        StringBuilder out = new StringBuilder();
        int total = 0;
        for (int k = 0; total < 100; k++) {
            int index = (k % 2 == 0 ? right : left).get(k / 2);
            if (k > 0) out.append(' ');
            out.append(index);
            total += forest[index];
        }
        System.out.println(out);
    }
}

package main

import (
	"io"
	"os"
	"strconv"
)

var data []byte
var pos int

func nextInt() int64 {
	for pos < len(data) && data[pos] <= ' ' {
		pos++
	}
	neg := false
	if pos < len(data) && data[pos] == '-' {
		neg = true
		pos++
	}
	var r int64
	for pos < len(data) && data[pos] >= '0' && data[pos] <= '9' {
		r = r*10 + int64(data[pos]-'0')
		pos++
	}
	if neg {
		return -r
	}
	return r
}

func main() {
	data, _ = io.ReadAll(os.Stdin)
	n, bird := int(nextInt()), int(nextInt())
	forest := make([]int, n)
	for i := range forest {
		forest[i] = int(nextInt())
	}
	// Sticks on each side, ordered from nearest to farthest from the nest.
	var left, right []int
	for i := bird - 1; i >= 0; i-- {
		if forest[i] != 0 {
			left = append(left, i)
		}
	}
	for i := bird + 1; i < n; i++ {
		if forest[i] != 0 {
			right = append(right, i)
		}
	}
	out := []byte{}
	total := 0
	for k := 0; total < 100; k++ {
		side := right
		if k%2 == 1 {
			side = left
		}
		index := side[k/2]
		if k > 0 {
			out = append(out, ' ')
		}
		out = strconv.AppendInt(out, int64(index), 10)
		total += forest[index]
	}
	out = append(out, '\n')
	os.Stdout.Write(out)
}
